function countSpaces(text: string): int
    requires text != null
    ensures 0 <= countSpaces(text) <= text.Length
{
    var count := 0;
    var i := 0;
    while i < text.Length
        invariant 0 <= i <= text.Length
        invariant count == countSpaces(text[0..i])
    {
        if text[i] == ' ' {
            count := count + 1;
        }
        i := i + 1;
    }
    return count;
}

function countReplacements(text: string): int
    requires text != null
    ensures 0 <= countReplacements(text) <= text.Length
{
    var replacements := 0;
    var i := 0;
    while i < text.Length
        invariant 0 <= i <= text.Length
        invariant replacements == countConsecutiveSpaces(text[0..i])
    {
        if i > 0 && text[i] == ' ' && text[i-1] == ' ' {
            if i > 1 && text[i-1] == ' ' && text[i-2] == ' ' {
                replacements := replacements + 1; // count as a replacement
            }
        }
        i := i + 1;
    }
    return replacements;
}

function countConsecutiveSpaces(subtext: string): int
    requires subtext != null
    ensures 0 <= countConsecutiveSpaces(subtext) <= subtext.Length
{
    var count := 0;
    var i := 0;
    while i < subtext.Length
        invariant 0 <= i <= subtext.Length
    {
        if subtext[i] == ' ' {
            count := count + 1;
        }
        i := i + 1;
    }
    return count;
